var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`바로 붙여넣을 수 있는 Klipper 설정 블록과 매크로 - 시작 시퀀스, 필라멘트 처리, 입력 셰이핑, 베드 메시 등. 하나를 복사해 printer.cfg에 넣으세요 (Config Editor가 붙여넣기 좋은 곳입니다).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`도움말`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`설정 템플릿 정보`}},close:{t:0,b:{t:2,i:[{t:3}],s:`닫기`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`사용 방법`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`카테고리로 필터링해 매크로나 설정 블록을 찾으세요.`}},{t:0,b:{t:2,i:[{t:3}],s:`설명과 필요한 섹션을 확인하세요.`}},{t:0,b:{t:2,i:[{t:3}],s:`템플릿을 복사해 설정에 붙여넣고 값을 조정하세요.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`이것이 무엇인가요`}},body:{t:0,b:{t:2,i:[{t:3}],s:`자주 쓰는 Klipper 빌딩 블록을 엄선한 모음입니다: gcode_macros (PRINT_START, PAUSE/RESUME, 필라멘트 로드/언로드, M600)와 설정 섹션 ([input_shaper], [bed_mesh], [firmware_retraction], …). 이들은 출발점일 뿐이니 각각 읽어보고 본인 장비에 맞게 튜닝하세요.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`템플릿 삽입하기`}},body:{t:0,b:{t:2,i:[{t:3}],s:`템플릿을 복사한 뒤 printer.cfg에 붙여넣으세요 - Config Editor의 Raw 보기가 편리한 위치입니다. 저장 후 펌웨어 재시작으로 적용됩니다. 항상 값을 먼저 검토하세요. 여기 기본값은 합리적이지만 본인 프린터에 맞춰진 것은 아닙니다.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`필요한 섹션`}},body:{t:0,b:{t:2,i:[{t:3}],s:`각 템플릿은 자신이 정의하거나 의존하는 설정 섹션을 나열합니다. 어떤 섹션이 설정에 이미 있다면 중복을 붙여넣지 말고 키를 병합하세요 (중복 섹션은 시작 시 거부됩니다).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`용어집`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`템플릿`}},def:{t:0,b:{t:2,i:[{t:3}],s:`printer.cfg에 복사해 넣는, 바로 붙여넣을 수 있는 Klipper 설정 또는 매크로 G-code 조각입니다.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`설정에서 정의하는 이름이 붙은 명령어(예: PRINT_START)로, 일련의 G-code를 실행합니다.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`섹션`}},def:{t:0,b:{t:2,i:[{t:3}],s:`[대괄호]로 묶인 설정 블록(예: [bed_mesh])으로, Klipper 설정이 묶이는 단위입니다.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`카테고리`}},all:{t:0,b:{t:2,i:[{t:3}],s:`전체 카테고리`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`복사`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`복사됨!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`섹션: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:3,v:`템플릿 `},{t:4,k:`n`},{t:3,v:`개`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`템플릿 불러오는 중…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`템플릿을 불러오지 못했습니다.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`이 카테고리에 템플릿이 없습니다.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`다시 시도`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`설정 블록`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`매크로`}}}}};export{e as default};